// This Verus program implements the “numpy_where” function:
// Given three equally‐sized arrays (a boolean mask, and two f32 arrays x and y),
// it returns a new f32 array `result` of the same length such that for each
// index i, result[i] = x[i] if mask[i] is true, and = y[i] otherwise.

use verus::prelude::*;

verus! {

    /// For each i in 0..cond.len(), picks x[i] when cond[i] is true,
    /// else picks y[i].
    pub fn numpy_where(cond: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32>
        requires
            // all three vectors have the same length
            cond.len() == x.len(),
            x.len() == y.len(),
        ensures
            // result has exactly that length
            result.len() == cond.len(),
        ensures
            // for every valid index i, the selection rule holds
            forall |i: usize|
                i < cond.len() ==>
                    if cond[i] { result[i] == x[i] } else { result[i] == y[i] }
    {
        let n = cond.len();
        // prepare an output vector with capacity n
        let mut res: Vec<f32> = Vec::with_capacity(n);

        // We'll fill res element by element.
        // Loop invariant ensures:
        //   1) 0 <= i <= n
        //   2) res.len() == i
        //   3) for all j < i, res[j] obeys the same selection rule
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                res.len() == i,
                forall |j: usize|
                    j < i ==>
                        if cond[j] { res[j] == x[j] } else { res[j] == y[j] },
            decreases n - i
        {
            // safe indexing because i < n
            let c  = cond[i];
            let xv = x[i];
            let yv = y[i];
            if c {
                res.push(xv);
            } else {
                res.push(yv);
            }
            i += 1;
        }

        // At this point i == n, so res.len() == n and the invariant
        // guarantees the full array satisfies the specification.
        res
    }

}